"""Grounded EKP cases. Alternatives are cases, never simultaneous assertions.

The workbook manifest is checked by the coverage test. An unhandled type fails
explicitly, rather than inventing a vaguely related emergency with a language model.
"""
from dataclasses import dataclass, field
from functools import lru_cache
import json
from pathlib import Path
import re


@dataclass
class Profile:
    family: str
    cases: tuple[str, ...]
    details: tuple[str, ...] = ()
    unknowns: tuple[str, ...] = ('Точное время начала мне неизвестно.',)
    flags: dict[str, bool] = field(default_factory=dict)
    setting: str = 'street'


def profile(family, cases, details=(), unknowns=(), flags=None, setting='street'):
    if isinstance(cases, str):
        cases = tuple(cases.split('|'))
    return Profile(family, tuple(cases), tuple(details), tuple(unknowns) or
                   ('Могу сообщить только то, что вижу сейчас.',), flags or {}, setting)


@lru_cache
def manifest():
    data = json.loads(Path(__file__).with_name('ekp_generation_manifest.json').read_text())
    return {item['code']: item for item in data['items']}


def text_of(t):
    return ' '.join((t['title'], *t['features'])).lower().replace('ё', 'е')


def no_victims(value):
    return bool(re.search(r'нет\s+пострадавш|без\s+пострадавш|пострадавш\w*\s+нет',value))


def object_name(t):
    """One specific object, selected from the normative alternatives."""
    exact = {
      '1990096':'мотоцикл', '1990176':'вентиляционная шахта метро',
      '1030101':'вагон метро','1030102':'вагон метро','1040101':'вагон МЦК','1040102':'вагон МЦК',
      '1020301':'автомобиль','1020302':'автомобиль','1020401':'грузовик с опасным грузом','1020402':'грузовик с опасным грузом',
      '7010603':'железнодорожные провода',
      '3010700':'узел связи','3010800':'квартира с газовым оборудованием','3010900':'газовый баллон',
      '3011500':'коммуникационный колодец','3011800':'участок улицы',
      '3020101':'вагон метро','3020201':'вагон МЦК','3020400':'служебный автомобиль',
      '3020502':'автовокзал','3020503':'автобусная остановка','3020700':'участок улицы',
      '3020801':'железнодорожный состав','3020803':'железнодорожное депо',
      '3020901':'самолёт','3021001':'судно',
      '4100000':'вагон метро','4120000':'вагон МЦК','4240000':'коммуникационный узел','4280000':'здание мэрии',
      '15070200':'пассажирский поезд','15070300':'вагон метро','15070400':'вагон МЦК',
      '15070600':'самолёт','15070700':'пассажирское судно','15070800':'автомобиль скорой помощи',
      '15070900':'машина газовой службы','15071000':'служебный автомобиль',
      '15090700':'склад с оружием','15090800':'телецентр','15090900':'военный объект',
      '15091000':'отдел полиции','15091100':'офис политической организации','15091200':'банк',
      '24030000':'участок проезжей части','24060000':'узел связи','24070000':'газопровод',
      '24080000':'линия электропередачи','24090000':'железнодорожная станция','24100000':'военный объект',
    }
    if t['code'] in exact: return exact[t['code']]
    title = t['title'].lower()
    if ':' in title:
        name = title.split(':', 1)[1].strip()
        fixes = {'нии':'научно-исследовательский институт', 'тэц':'теплоэлектроцентраль',
                 'ж-д цистерна':'железнодорожная цистерна', 'будка консъержки':'будка консьержа',
                 'шиномонтаж авто':'шиномонтажная мастерская', 'замыкание электропроводки':'электропроводка',
                 'вагон электрички (вагон электропоезда)':'вагон электрички',
                 'учебное заведение':'школа','лечебное заведение':'больница',
                 'общественное место':'торговый центр','жилой дом':'многоквартирный дом'}
        name = fixes.get(name, name)
        if not re.search(r'проч|/|при дтп|опасн|транспорт|метро|мцк|эстакад|переход|производств', name):
            return name
    value = text_of(t)
    # Priority keeps gas equipment in a flat distinct from the flat itself.
    objects = (
        (r'газовая колонка', 'газовая колонка'), (r'газовая плита|газплита', 'газовая плита'),
        (r'мусоропровод', 'мусоропровод'), (r'электросчетчик', 'электросчётчик'),
        (r'электрощит|щитова', 'электрощитовая'), (r'проводк', 'электропроводка'),
        (r'контактн', 'контактная сеть'), (r'лэп|электрические провода', 'линия электропередачи'),
        (r'подземн.*коммуникац|кабельный коллектор', 'кабельный коллектор'),
        (r'наземн.*коммуникац', 'наземный коммуникационный узел'),
        (r'газохранил', 'газохранилище'), (r'газопровод', 'газопровод'),
        (r'нефтехранил', 'нефтехранилище'), (r'нефтебаз', 'нефтебаза'), (r'нефтепровод', 'нефтепровод'),
        (r'гидросооруж|гидротехничес', 'плотина'), (r'азс', 'автозаправочная станция'),
        (r'\bмцк\b', 'станция МЦК'), (r'\bметро\b|метрополитен', 'станция метро'),
        (r'аэропорт|аэровокзал', 'аэропорт'), (r'воздушн|самолет', 'самолёт'),
        (r'водный транспорт|транспорт водный|судн|корабл', 'судно'),
        (r'\bпорт\b|причал', 'причал'), (r'вокзал|платформ|жд станц', 'железнодорожная платформа'),
        (r'железнодорожн.*транспорт|жд транспорт|транспорт жд|поезд|ж/д', 'поезд'),
        (r'автобус|общественн.*транспорт', 'автобус'), (r'автомашин|автомобил|машин', 'автомобиль'),
        (r'транспорт.*проч|проч.*транспорт|угроза взрыва транспорт', 'трактор'),
        (r'балкон', 'балкон'), (r'лифт', 'лифт'), (r'лестничн', 'лестничная клетка'),
        (r'подвал', 'подвал'), (r'подъезд', 'подъезд'), (r'\bквартир', 'квартира'),
        (r'частн.*дом|дом частный', 'частный дом'), (r'жил.*дом|дом жил|жил\w* здани|многоквартир', 'многоквартирный дом'),
        (r'дача', 'дачный дом'), (r'учебное|школ|гимназ|лицей', 'школа'),
        (r'лечебное|больниц', 'больница'), (r'административ', 'административное здание'),
        (r'опасный|производств', 'производственный цех'),
        (r'строительные леса', 'строительные леса'), (r'кран', 'башенный кран'),
        (r'котлован', 'котлован'), (r'мачт|освещен', 'опора освещения'),
        (r'тоннель', 'тоннель'), (r'переход', 'пешеходный переход'), (r'эстакад', 'эстакада'), (r'мост', 'мост'),
        (r'гараж', 'гараж'), (r'\bлес\b|\bлесу\b|\bпарк\w*', 'лесной участок'),
        (r'общественное место', 'торговый центр'),
    )
    # A criterion like “vibration from a nearby metro” isn't the damaged object.
    for fragment in (title, *t['features'][:2]):
        for pattern, name in objects:
            if re.search(pattern,fragment.lower().replace('ё','е')):
                return name
    return 'склад'


def site(t):
    obj = object_name(t)
    return f'Это {obj}.'


def fire_profile(t):
    value = text_of(t)
    obj = object_name(t)
    if 'сигнализац' in value:
        return profile('fire-alarm', 'Сработала пожарная сигнализация, слышен непрерывный сигнал.|На панели пожарной сигнализации горит индикатор тревоги, звучит сирена.',
                       (site(t), 'Дыма и открытого пламени с моего места не видно.'),
                       ('Причину срабатывания не знаю.', 'В другие помещения заглянуть не могу.'), setting='building')
    if 'запах' in value or 'гари' in value:
        return profile('burning-smell', 'Чувствую сильный запах гари, но источник не вижу.|Здесь появился запах горелой изоляции, видимого пламени нет.|Запах гари не проходит, дым с моего места не виден.',
                       (site(t),), ('Не могу определить, откуда именно идёт запах.',), setting='building')
    smoke = 'задимлен' in value or 'задымлен' in value or ('дым' in t['features'] and 'открытое пламя' not in t['features'])
    if smoke:
        details=[site(t)]
        if 'при дтп' in value: details.append('Перед этим здесь столкнулись две машины.')
        if 'опасный груз' in value: details.append('На грузовике есть маркировка опасного груза, название груза мне неизвестно.')
        return profile('smoke', 'Вижу густой дым, открытого пламени с моего места не видно.|Оттуда идёт серый дым, он не рассеивается.|Дым усиливается, становится трудно разглядеть источник.',
                       tuple(details), ('Что именно тлеет, определить не могу.', 'Своё место не покидаю, дальше не видно.'))
    plural = obj in ('провода','покрышки автомобильные','шпалы','строительные леса','наземные коммуникации','подземные коммуникации')
    anchor = f"{'Горят' if plural else 'Горит'} {obj}."
    if re.search(r'провод|щит|счетчик|подстанц|обмотк|контактн', value):
        cases = (anchor+' Вижу пламя и искры.', anchor+' Виден огонь, пахнет горелой изоляцией.', anchor+' Из повреждённого участка выходят языки пламени.')
    elif re.search(r'трава|пух|мусор|покрышк|торф|шпал|дерево|лес|свалк|костер', value):
        cases = (anchor+' Вижу открытое пламя.', anchor+' Огонь уже захватил соседний участок.', anchor+' Видны отдельные очаги огня и дым.', anchor+' Пламя раздувает ветер.')
    elif re.search(r'автобус|автомашин|автомобил|вагон|трамвай|троллейбус|мототранспорт', value):
        cases = (anchor+' Пламя видно снаружи.', anchor+' Вижу огонь в передней части.', anchor+' Пламя распространяется по боковой части.')
    else:
        cases = (anchor+' Вижу открытое пламя.', anchor+' Виден огонь и плотный дым.', anchor+' Языки пламени становятся выше.')
    flags = {'gasified':True} if re.search(r'газопровод|газохранил|газовая|газов.*плит', value) else {}
    p = profile('fire', cases, (), ('Что стало причиной огня, не знаю.', 'Внутри всё не просматривается.'), flags)
    if 'при дтп' in value:
        p.cases = tuple(c+' Перед этим здесь столкнулись две машины.' for c in p.cases)
    if 'опасный груз' in value:
        p.cases = tuple(c+' На кузове есть маркировка опасного груза, его название не знаю.' for c in p.cases)
    return p


