def utility_profile(t):
    code, value = t['code'], text_of(t)
    cases = UTILITY.get(code)
    details=[]
    flags={}
    if code.startswith('1406') and cases is None:
        place='на проезжей части' if 'проезж' in value else 'на тротуаре' if 'тротуар' in value else 'на газоне' if 'газон' in value else 'во дворе'
        if 'покрыти' in value: cases=f'{place.capitalize()} повреждено покрытие, край асфальта выступает.|{place.capitalize()} глубокие ямы в асфальте.'
        else:
            cases=f'{place.capitalize()} провалился грунт, образовалась яма.|{place.capitalize()} провал, виден обрушившийся край.'
            if 'более 2' in value: details.append('Размер провала больше двух метров по длине и ширине.')
            elif '2х2' in value or '2*2' in value: details.append('Размер провала не больше двух метров по длине и ширине.')
            if 'коммуникац' in value: details.append('В провале видны повреждённые трубы.')
            if 'фонтан' in value: details.append('Из провала бьёт фонтан воды.')
            elif 'утечк' in value: details.append('Из провала течёт вода.')
    if code.startswith('14070') and cases is None:
        kind=code[4:6]
        cases={
          '01':'Крышка колодца подскакивает и хлопает.|При проезде машин крышка люка громко бьёт по краям.',
          '02':'Вокруг колодца разрушен асфальт.|По краю люка асфальт раскрошился, видна глубокая щель.',
          '03':'Люк открыт, крышка лежит рядом.|Крышка люка сдвинута, часть отверстия открыта.|Крышка люка расколота, виден открытый колодец.',
          '04':'Крышка люка просела ниже дороги.|Люк сильно утоплен относительно асфальта, вокруг углубление.',
        }[kind]
        owner={'02':'газовой службы','03':'телефонной связи','04':'городской электросетевой компании','05':'электросетевой компании','06':'водоканала','07':'службы водостоков','08':'теплоснабжающей компании','09':'службы коллекторов'}.get(code[-2:])
        if owner: details.append(f'Я сотрудник обслуживающей организации: это колодец {owner}.')
    if code.startswith('1408') and cases is None:
        fallen=code.startswith('140801')
        target=next((noun for needle,noun in (('электрическ','электрические провода'),('контактн','провода контактной сети'),('человек','человека'),('машин','автомобиль'),('животн','животное'),('оперативн','проезд для экстренных служб'),('проезж','проезжую часть')) if needle in value),'дворовую дорожку')
        if fallen: cases=f'Дерево упало на {target}.|На {target} лежит упавшее дерево.'
        elif target in ('электрические провода','провода контактной сети'): cases=f'Дерево наклонилось и опирается на {target}.|Ветки дерева нависли на {target}, ствол сильно наклонён.'
        else: cases=f'Дерево сильно наклонилось, нависает над дорожкой.|У дерева поднялись корни, ствол наклонён над проходом.'
        if 'на человека' in value: details.append('Человек придавлен, самостоятельно выбраться не может.')
        if 'есть пострадавшие' in value: details.append('Человек в машине жалуется на боль.')
        if 'оперативных' in value: details.append('Машина экстренной службы не может проехать.')
        if code=='14080108': cases='Дерево упало поперёк дороги и перекрыло проезд экстренным службам.|Упавшее дерево не даёт проехать машине экстренной службы.'
        if code=='14080209': cases='Дерево сильно наклонилось над проезжей частью.|У дерева поднялись корни, ствол нависает над дорогой.'
    if code.startswith(('1411','1412')):
        contact=code.startswith('1412'); wire='контактной сети' if contact else 'электросети'
        if 'провис' in value: cases=f'Провода {wire} низко провисли.|Провода {wire} свисают почти до уровня головы.'
        elif 'искр' in value: cases=f'На проводах {wire} видны искры.|Провода {wire} трещат и искрят.'
        elif 'обрыв' in value:
            target='на автомобиле' if 'автомашин' in value else 'на человеке' if 'на человека' in value else 'на животном' if 'на животное' in value else 'на проезжей части' if 'проезж' in value else 'на земле'
            cases=f'Оборванный провод {wire} лежит {target}.|Вижу обрыв провода {wire}, его конец {target}.'
        elif 'посторонний' in value: cases='На контактных проводах висит посторонний предмет.|На контактной сети зацепился большой кусок плёнки.'
        elif 'горит' in value: cases='Опора горит, вижу открытое пламя у оборудования.|На опоре видно пламя и дым.'
        elif 'паден' in value or 'упала' in value:
            target='на человека' if 'на человека' in value else 'на животное' if 'на животное' in value else 'на землю'
            cases=f'Опора упала {target}.|Вижу упавшую опору, она рухнула {target}.'
        else: cases='Опора повреждена, крепления деформированы.|У опоры сломано крепление, видны повреждённые провода.'
        if ('пострадавш' in value and not no_victims(value)) or 'на человека' in value: details.append('Есть пострадавший, нужна медицинская помощь.')
        if 'проезж' in value: flags['traffic_blocked']=True; details.append('Проезд перекрыт проводом, машины стоят.')
    if cases is None: raise ValueError('Не разобрано коммунальное событие '+code)
    injured=not no_victims(value) and bool(re.search(r'пострадавш|на человека|падение человека|падение в люк|медицинская',value))
    if no_victims(value): details.append('На месте сообщают, что пострадавших нет.')
    flags.update({'victims':injured,'medical_help':injured})
    if injured or code in ('14100102','14101400','14101900'): flags['life_danger']=True
    if code.startswith('141001'): flags['access_blocked']=True
    if code.startswith('140207'): flags['construction']=True
    setting='building' if code.startswith(('1403','1404','1405','1410')) else 'street'
    return profile('utility-'+code[2:6],cases,tuple(details),('Когда это началось, точно не знаю.', 'Осмотреть повреждение с другой стороны не могу.'),flags,setting)


