def offense_profile(t):
    code, value = t['code'], text_of(t)
    # Existing richer apartment/garage/store and abandoned-car builders take precedence.
    if code not in ('15020300','15020400','15020500') and re.search(r'вскрыт|вскрывают|вскрыва',value):
        ongoing='вскрывают' in value or 'вскрыва' in t['title'].lower()
        obj='автомобиль' if re.search('автомашин|автомобил',t['title'],re.I) else 'квартира'
        return profile('intrusion-active' if ongoing else 'intrusion-found',
                       f'Незнакомый человек пытается вскрыть дверь. Это {obj}.|Вижу человека с инструментом у замка. Это {obj}.' if ongoing else
                       f'Дверной замок повреждён, дверь открыта. Это {obj}.|У замка следы взлома, дверь приоткрыта. Это {obj}.',(),('Кто находится внутри, снаружи не видно.',),{'offense':True},'building' if obj=='квартира' else 'street')
    if 'брошен' in value or 'брошенн' in value:
        return profile('abandoned-vehicle','Автомобиль много дней стоит на одном месте, владельца не видно.|Машина давно стоит без движения, хозяина рядом нет.',(),('Кто владелец автомобиля, не знаю.',))
    if code.startswith('1507'):
        return profile('hostage',f'Внутри удерживают людей и не дают им выйти, поступило сообщение об угрозах. {site(t)}|Изнутри человек сообщил, что людей удерживают силой и угрожают им. {site(t)}',(),('Точное число удерживаемых людей неизвестно.',),{'offense':True,'life_danger':True})
    if code.startswith('1509'):
        if 'на объект' in value or code[4:6] in ('07','08','09','10','11','12'):
            cases=f'Группа людей силой пытается проникнуть внутрь, ломает дверь. {site(t)}|Люди напали на объект, бьют по двери и угрожают сотрудникам. {site(t)}'
        else:
            person={'15090101':'сотрудника полиции','15090102':'сотрудника ФСБ','15090103':'сотрудника Росгвардии','15090104':'сотрудника МЧС','15090105':'сотрудника скорой помощи','15090106':'сотрудника газовой службы','15090107':'сотрудника телефонной службы','15090108':'сотрудника коммунальной службы','15090200':'военнослужащего','15090300':'депутата','15090400':'адвоката','15090500':'священнослужителя','15090600':'судью','15091300':'журналиста','15091400':'инкассатора','15091401':'инкассатора'}.get(code,'человека')
            cases=f'Вижу нападение на {person}, нападающий бьёт его.|На {person} напали двое людей, конфликт продолжается.'
            if code=='15091401': cases=f'На {person} напали с оружием, требуют отдать ценности.|Угрожая ножом, у инкассатора забирают сумку.'
        return profile('assault',cases,(),('Личность нападавших мне неизвестна.',),{'offense':True,'life_danger':True})
    if code.startswith('1521') and code[4:6] not in ('14','15'):
        kind={'01':'автомобиль','02':'пожарный автомобиль','03':'полицейский автомобиль','04':'автомобиль скорой помощи','05':'автомобиль газовой службы','06':'строительная спецтехника','07':'служебный автомобиль','08':'автомобиль электросетевой компании','09':'автобус','10':'самолёт','11':'катер','12':'железнодорожный поезд','13':'железнодорожный вагон'}[code[4:6]]
        duration='десять минут' if code.endswith('01') else 'больше часа'
        return profile('vehicle-theft-recent' if code.endswith('01') else 'vehicle-theft-old',f'Без разрешения забрали {kind}, это произошло {duration} назад.|Сообщаю об угоне: {kind} отсутствует, с момента угона прошло {duration}.',(),('Где транспорт сейчас, не знаю.',),{'offense':True})
    cases=OFFENSE.get(code[:6])
    if cases is None: raise ValueError('Не разобрано нарушение порядка '+code)
    if code=='15050702': cases='У водителя силой отобрали автомобиль и уехали.|Человека вытолкнули из машины и завладели ею.'
    if code=='15050801': cases='Инкассаторам угрожают оружием и забирают сумку с ценностями.|На инкассаторов напали с ножом, требуют деньги.'
    if code=='15050802': cases='Водителю угрожали оружием и отобрали машину.|Угрожая ножом, нападавшие завладели автомобилем.'
    if code in ('15060202','15250502'): cases='На улице дерутся больше десяти человек.|В драке участвуют примерно пятнадцать человек.'
    if code=='15130601': cases='На пассажирском судне найдена бесхозная сумка с проводами.|На причале стоит бесхозная коробка, владелец не находится.'
    if code=='15220601': cases='Человек угрожает прохожему ударить его палкой.|Человек угрожает расправой и показывает нож.'
    if code=='15220602': cases='Человек стреляет из оружия в общественном месте.|Человек применяет оружие, вижу выстрелы.'
    if code=='15220603': cases='Люди ломают павильон автобусной остановки.|У остановки разбивают стекло и ломают скамью.'
    if code=='15250101': cases='У входа большая группа молодых людей, проход затруднён.|На площади скопилось много подростков, они занимают весь проход.'
    if code=='15250601': cases='Толпа ведёт себя агрессивно, люди толкают прохожих и угрожают.|Группа людей бросает предметы и кричит угрозы.'
    if code=='15250602': cases='В плотной толпе давка, люди не могут свободно двигаться.|Толпа прижала людей к ограждению, слышны крики о помощи.'
    flags={'offense':True}
    if code=='15200100': flags.update(victims=True,medical_help=True,life_danger=True)
    if code[:6] in ('152500','152501','152506') or code in ('15060202','15250502'): flags['mass_event']=True
    if code.startswith('152501') or code=='15250600':
        cases='|'.join(part+' Людей больше десяти.' for part in cases.split('|'))
    if code=='15250602': flags['life_danger']=True
    # A crowd, a civil dispute or suspicious appearance alone isn't a confirmed offense.
    if code[:6] in ('150400','150802','151301','151302','151303','151304','151305','151306','151307','151400','151409','151601','151602','151603','152501','152502','152503','152504','152506') or code in ('15200300',): flags['offense']=False
    return profile('offense-'+code[:6],cases,(),('Дополнительных примет сейчас сообщить не могу.', 'Точное время начала мне неизвестно.'),flags)


