def road_profile(t):
    code=t['code']
    if code in ('16030000','16030100'):
        return profile('abandoned-vehicle','Машина много дней стоит на одном месте, хозяина нет.|Автомобиль давно стоит без движения, владельца не видно.')
    return profile('road-'+code,ROAD[code],(),('Размер препятствия с моего места точно не определить.',) if 'консультац' not in t['title'].lower() else ('Более подробных сведений у меня нет.',))


