def person_profile(t):
    code, value = t['code'], text_of(t)
    cases=PERSON.get(code)
    if code.startswith(('170201','170202')):
        forest=code.startswith('170201'); minor=code.endswith('01'); dependent=code.endswith('02')
        person='пятнадцатилетний подросток' if minor else 'человек, который по состоянию здоровья не может ориентироваться самостоятельно' if dependent else 'взрослый человек'
        cases=f'Пропал {person}, последний раз был в лесу, на связь не выходит.|{person.capitalize()} не вернулся из леса, найти его не получается.' if forest else f'Пропал {person}, домой не вернулся и на связь не выходит.|{person.capitalize()} ушёл из дома, сейчас его местонахождение неизвестно.'
    if code.startswith(('170206','170207','170301','170302')):
        child=code.startswith(('170206','170302'))
        person='ребёнка' if child else 'человека'
        cases=f'Незнакомые люди силой увели {person}, он сопротивлялся.|{person.capitalize()} забрали против воли, его удерживали за руки.'
        if code.endswith('01'): cases=f'Незнакомые люди силой посадили {person} в машину и уехали.|{person.capitalize()} против воли увезли на автомобиле.'
    if code.startswith(('171001','171002','171003','171004')):
        action={'01':'Человек повесился, не реагирует на голос.','02':'Человек намеренно принял много таблеток, рядом упаковки.','03':'Человек намеренно порезал себе руку, идёт кровь.','04':'Человек выстрелил в себя, видна рана.'}[code[4:6]]
        fatal=code.endswith('01')
        cases=(action+' Смерть уже подтверждена врачом.|Передаю сообщение о самоубийстве. '+action+' На месте врач, смерть подтверждена.') if fatal else (action+' Нужна срочная медицинская помощь.|Рядом попытка самоубийства. '+action)
    if cases is None: raise ValueError('Не разобрана опасность человеку '+code)
    threat=code in ('17010800','17010900','17011000','17011100','17041200','17041300','17070100','17090000','17100900','17101000') or code.startswith(('1702','1703'))
    no_med=code in ('17080300','17080500','17080700','17080800','17080900','17081000','17081101','17081102','17081103','17100500')
    injured=not threat and not no_med and code not in ('17080400','17080600')
    flags={'victims':injured,'medical_help':injured,'life_danger':not no_med}
    if code.startswith(('170206','170207','1703')) or code in ('17010300','17010700','17010900','17011000','17090000'): flags['offense']=True
    if code in ('17080100','17080200'): flags['access_blocked']=True
    if code in ('17080400','17080600'): flags['access_blocked']=True
    if code in ('17080900','17100500'): flags.update(gasified=True,life_danger=True)
    setting='forest' if code.startswith('170201') else 'water' if code.startswith('1707') or code in ('17040600',) else 'rail' if code in ('17040300','17040400','17040500','17040900','17041000','17041100') or code.startswith('1705') else 'building' if code.startswith('1708') else 'street'
    return profile('person-'+code[:6],cases,(),('Причину произошедшего точно не знаю.', 'Другие обстоятельства с моего места не видны.'),flags,setting)


