def death_profile(t):
    code, value=t['code'],text_of(t)
    if code=='19010300': return profile('decomposition-smell','Из квартиры сильный запах разложения, жилец не отвечает.|От двери квартиры идёт запах, похожий на трупный, войти не могу.',(),('Что находится внутри, мне неизвестно.',),setting='building')
    if 'части' in value:
        cases='Вижу останки, похожие на части человеческого тела.|Здесь предметы, похожие на части тела человека, нужна проверка.'
    elif 'убийство' in value:
        cases='Врач подтвердил смерть человека, рядом видны следы насилия, прошу помощь полиции.|Смерть уже подтверждена врачом, сообщаю о возможном убийстве: рядом следы борьбы.'
    elif code in ('19010101','19010102'):
        cases='Родственник умер дома, нужна медицинская констатация смерти.|Дома человек без признаков жизни, просим направить врача для констатации смерти.'
    else:
        cases='Здесь неподвижное тело человека, на обращения реакции нет.|Вижу тело человека, признаков движения нет, причина неизвестна.'
    location='В квартире.' if code.startswith('1901') else 'На железнодорожной платформе.' if code.startswith('190202') else 'На станции метро.' if code.startswith('190203') else 'На платформе МЦК.' if code.startswith('190204') else 'В колодце.' if code.startswith('190205') else 'В воде.' if code.startswith('190206') else 'На улице.'
    details=[location]
    if code=='19010101': details.append('Сейчас одиннадцать часов утра.')
    if code=='19010102': details.append('Сейчас двадцать три часа.')
    return profile('death-'+code[:6],cases,tuple(details),('Личность человека мне неизвестна.',) if not code.startswith('1901') else ('Причину смерти может определить только врач.',),
                   {'victims':True,'medical_help':True,'offense':'убийство' in value},'water' if code.startswith('190206') else 'rail' if code.startswith(('190202','190203','190204')) else 'building' if code.startswith('1901') else 'street')


