def case_contexts(p):
    """Optional facts carry their own dispatch flags; complexity never adds injuries."""
    if p.family in ('fire','smoke','explosion','collapse','collapse-part'):
        symptom = 'сильный кашель после дыма' if p.family=='smoke' else 'ожог руки' if p.family=='fire' else 'боль в ноге после происшествия'
        return (
            ('',{}),
            ('Пострадавших с моего места не вижу.',{'victims':False}),
            (f'Рядом человек жалуется: {symptom}, просит медицинской помощи.',{'victims':True,'medical_help':True}),
            (f'Рядом два человека жалуются: {symptom}, нужна медицинская помощь.',{'victims':True,'medical_help':True}),
        )
    return (('',{}),)
